WITH revenue AS (SELECT p.category_id,SUM(i.quantity*i.unit_price_cents) AS cents FROM products p JOIN order_items i ON i.product_id=p.product_id JOIN orders o ON o.order_id=i.order_id WHERE o.status='paid' GROUP BY p.category_id) SELECT c.category_name,COALESCE(r.cents,0) AS revenue_cents FROM categories c LEFT JOIN revenue r ON r.category_id=c.category_id ORDER BY revenue_cents DESC,c.category_name;
